package com.northstar.order;import static com.northstar.order.CheckoutModels.*;import java.math.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;@Service @EnableConfigurationProperties(PayPalProperties.class)public class PayPalService{private final PayPalProperties cfg;private final RestClient paypal,catalog;public PayPalService(PayPalProperties c,@Value("${services.catalog-url}")String url){cfg=c;paypal=RestClient.builder().baseUrl(c.baseUrl()).build();catalog=RestClient.builder().baseUrl(url).build();}public Created create(Request r){check();BigDecimal total=r.items().stream().map(i->{Product p=catalog.get().uri("/api/products/{id}",i.productId()).retrieve().body(Product.class);if(p==null)throw new IllegalArgumentException("Unknown product");return p.price().multiply(BigDecimal.valueOf(i.quantity()));}).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(2,RoundingMode.HALF_UP);Map<?,?>x=paypal.post().uri("/v2/checkout/orders").header("Authorization","Bearer "+token()).header("PayPal-Request-Id",UUID.randomUUID().toString()).contentType(MediaType.APPLICATION_JSON).body(Map.of("intent","CAPTURE","purchase_units",List.of(Map.of("amount",Map.of("currency_code","USD","value",total.toPlainString()))))).retrieve().body(Map.class);return new Created(Objects.toString(x.get("id")),Objects.toString(x.get("status")));}public Captured capture(String id){check();Map<?,?>x=paypal.post().uri("/v2/checkout/orders/{id}/capture",id).header("Authorization","Bearer "+token()).header("PayPal-Request-Id",UUID.randomUUID().toString()).contentType(MediaType.APPLICATION_JSON).body(Map.of()).retrieve().body(Map.class);Object v=x.get("payer");Map<?,?>p=v instanceof Map<?,?>m?m:Map.of();return new Captured(Objects.toString(x.get("id")),Objects.toString(x.get("status")),Objects.toString(p.get("email_address"),""));}private String token(){String b=Base64.getEncoder().encodeToString((cfg.clientId()+":"+cfg.clientSecret()).getBytes(StandardCharsets.UTF_8));Map<?,?>x=paypal.post().uri("/v1/oauth2/token").header("Authorization","Basic "+b).contentType(MediaType.APPLICATION_FORM_URLENCODED).body("grant_type=client_credentials").retrieve().body(Map.class);return Objects.toString(x.get("access_token"));}private void check(){if(cfg.clientId()==null||cfg.clientId().isBlank()||cfg.clientSecret()==null||cfg.clientSecret().isBlank())throw new IllegalStateException("PayPal sandbox credentials are not configured");}}
